<script setup lang="ts">
import AppLoading from './AppLoading.vue'
import { computed,ref } from 'vue'
import { state,submittingOperations,rows,retryPending,discardBlocked,refresh,setError } from '../state/household'
import { money } from '../lib/money'
const working=ref('')
const visiblePending=computed(()=>state.pending.filter(item=>!(item.operation.kind==='wishlist.reorder'&&item.state==='queued'&&state.online&&submittingOperations.has(item.operation.operation_id))))
async function retry(id:string){working.value=id;try{await retryPending(id)}catch(e){setError(e)}finally{working.value=''}}
async function review(){try{await refresh();state.notice='Latest records loaded. Review the changed item, discard the rejected action, and submit a new action with your intended changes.'}catch(e){setError(e)}}
async function discard(id:string){if(!confirm('Discard this rejected action from this device? Confirmed server records will remain.'))return;try{await discardBlocked(id)}catch(e){setError(e)}}
function label(kind:string){return kind==='purchase.create'?'Purchase':kind==='request.create'?'Approval request':kind==='vote.set'?'Approval change':'Saved change'}
</script>
<template><section v-if="visiblePending.length" class="notice pending-panel"><AppLoading v-if="working" compact /><details :open="visiblePending.some(x=>x.state==='blocked')"><summary>{{visiblePending.length}} action(s) saved on this device · {{visiblePending.some(x=>x.state==='blocked')?'Review needed':'Waiting to sync'}}</summary><div v-for="item in visiblePending" :key="item.operation.operation_id" class="row"><div class="row-main"><strong>{{label(item.operation.kind)}}</strong><p>{{rows('users').find(x=>x.id===item.operation.actor_id)?.name??'Household setup'}} · {{'item' in item.operation.data?item.operation.data.item:'name' in item.operation.data?item.operation.data.name:''}} <template v-if="'amount_minor' in item.operation.data&&typeof item.operation.data.amount_minor==='number'"> · {{money(item.operation.data.amount_minor)}}</template></p><p>{{item.error??'Not yet confirmed by the household server.'}}</p><small>{{item.state==='blocked'?'This action was rejected; review the latest records before submitting a replacement.':'The original actor, date and submission are preserved.'}}</small></div><div class="actions"><template v-if="item.state==='blocked'"><button class="button small" @click="review">Load latest records</button><button class="button small" @click="discard(item.operation.operation_id)">Discard rejected action</button></template><button v-else class="button small" :disabled="working===item.operation.operation_id" @click="retry(item.operation.operation_id)">Retry saved action</button></div></div></details></section></template>
